package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class MaxBetTest{
 @Test public void maxUsesOnlyUnlockedStepAndNeverSpends(){SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());long b=v.getBalance();v.maxBet();assertEquals(5,v.betIdx());assertEquals(b,v.getBalance());assertEquals(0,v.getSpinsDone());v.restore("500;0;1;0;0;10;0");v.maxBet();assertEquals(6,v.betIdx());}
 @Test public void pendingCollectBlocksMax(){SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.restore("500;0;1;0;0;2;0;0;;300;1");v.maxBet();assertEquals(1,v.betIdx());}
 @Test public void shortcutTouchOnlyChangesBet(){SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.layout(0,0,640,1040);long b=v.getBalance();float y=SlotsView.ctrlY(640,1040)+1040*.07f+640*.03f;v.onTouchEvent(android.view.MotionEvent.obtain(0,0,android.view.MotionEvent.ACTION_DOWN,640*.31f,y,0));assertEquals(5,v.betIdx());assertEquals(b,v.getBalance());assertEquals(0,v.getSpinsDone());}
 @GraphicsMode(GraphicsMode.Mode.NATIVE) @Test public void maxLabelPreview()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.layout(0,0,640,1040);v.maxBet();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(640,1040,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-maxbet.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}}
}
